from __future__ import absolute_import
from functools import partial
from taf.selenium.sbts.pages import alarms


class Alarms(alarms.Alarms):

    def __init__(self, driver, download_checker):
        super(Alarms, self).__init__(driver, download_checker)
        self._active_alarms = ActiveAlarmsPage(driver, download_checker)
        self._alarm_history = AlarmHistoryPage(driver, download_checker)


class AlarmsCommonAction(alarms.AlarmsCommonAction):

    def _get_alarms_info(self, timeout):
        alarm_list = []
        key_list = self.get_fields_info_from_row(self._ALARM_COLUMN_HEADER_XPATH, timeout)
        alarm_number = len(self.driver.find_elements_by_xpath(self._ALARMS_ROW_XPATH))
        for index in range(1, alarm_number + 1):
            alarms_severity_xpath = self._ALARMS_ROW_XPATH + "[{}]".format(index) + self._ALARMS_SEVERITY_XPATH
            severity = self.get_attribute_by_xpath(alarms_severity_xpath, 'class', timeout)

            alarm_info_xpath = self._ALARMS_ROW_XPATH + "[{}]//td[text()]".format(index)
            value_list = self.get_fields_info_from_row(alarm_info_xpath, timeout)
            value_list.insert(0, severity)

            alarm_list.append(dict(zip(key_list, value_list)))
        return alarm_list

    def get_alarms_info(self, alarm_filter, timeout, alarm_filter_xpath):
        self._input_filter_context(alarm_filter, timeout, alarm_filter_xpath)
        return self._get_alarms_info(timeout)


class ActiveAlarmsPage(alarms.ActiveAlarmsPage):

    def __init__(self, driver, download_checker):
        super(ActiveAlarmsPage, self).__init__(driver, download_checker)
        self._view_panel = ActiveAlarmsPageViewPanel(driver, download_checker)
        self.common_actions = {
            "get_active_alarm_info": self._view_panel.get_active_alarm_info,
        }
        self.__dict__.update(self.common_actions)


class ActiveAlarmsPageViewPanel(alarms.ActiveAlarmsPageViewPanel):

    def __init__(self, driver, download_checker):
        super(ActiveAlarmsPageViewPanel, self).__init__(driver, download_checker)
        common_action = AlarmsCommonAction(driver, download_checker)
        self.common_actions = {
            "get_active_alarm_info": partial(common_action.get_alarms_info,
                                             alarm_filter_xpath=self._ACTIVE_ALARM_FILTER_XPATH),
        }
        self.__dict__.update(self.common_actions)


class AlarmHistoryPage(alarms.AlarmHistoryPage):

    def __init__(self, driver, download_checker):
        super(AlarmHistoryPage, self).__init__(driver, download_checker)
        self._view_panel = AlarmHistoryPageViewPanel(driver, download_checker)
        self.common_actions = {
            "get_history_alarm_info": self._view_panel.get_history_alarm_info
        }
        self.__dict__.update(self.common_actions)


class AlarmHistoryPageViewPanel(alarms.AlarmHistoryPageViewPanel):

    def __init__(self, driver, download_checker):
        super(AlarmHistoryPageViewPanel, self).__init__(driver, download_checker)
        common_action = AlarmsCommonAction(driver, download_checker)
        self.common_actions = {
            "get_history_alarm_info": partial(common_action.get_alarms_info,
                                              alarm_filter_xpath=self._HISTORY_ALARM_FILTER_XPATH)
        }
        self.__dict__.update(self.common_actions)
